nav=''.join(f'<a href="#{i}">{t.split(". ",1)[1]}</a>' for i,t,b in sections)
body=''.join(f'<section id="{i}"><h2>{t}</h2>{b}</section>' for i,t,b in sections)
paths=['a-restoration/nearest/crop','a-restoration/realesrgan/crop','b-edit/crop','c-strip/crop']
frames=[[data(f'{p}/frame_{i:02d}.png') for i in range(10)] for p in paths]
js='''
const FRAME_DATA=__FRAMES__;
const names=['Original 2x','A Real-ESRGAN','B Frame edit','C Whole sheet'];
const cv=document.getElementById('animation-canvas'),ctx=cv.getContext('2d');
const slider=document.getElementById('frame'),play=document.getElementById('play');
let imgs=[],running=false,timer=null;
window.REVIEW_READY=false;
Promise.all(FRAME_DATA.map(row=>Promise.all(row.map(url=>new Promise(resolve=>{let im=new Image();im.onload=()=>resolve(im);im.src=url}))))).then(x=>{imgs=x;draw();window.REVIEW_READY=true});
function draw(){if(!imgs.length)return;let f=Number(slider.value),z=Number(document.getElementById('zoom').value),overlay=document.getElementById('overlay').checked,bg=document.getElementById('bg').value;
cv.width=1168*z;cv.height=244*z;ctx.scale(z,z);ctx.imageSmoothingEnabled=false;ctx.fillStyle='#17212b';ctx.fillRect(0,0,1168,244);ctx.font='14px Arial';
for(let j=0;j<4;j++){ctx.fillStyle='white';ctx.fillText(names[j],j*292+8,20);let x=j*292,y=36;
if(bg==='checker'){for(let yy=0;yy<208;yy+=16)for(let xx=0;xx<292;xx+=16){ctx.fillStyle=((xx/16+yy/16)%2)?'#393d42':'#31353a';ctx.fillRect(x+xx,y+yy,Math.min(16,292-xx),Math.min(16,208-yy))}}else{ctx.fillStyle=bg;ctx.fillRect(x,y,292,208)}
if(!overlay){ctx.drawImage(imgs[j][f],x,y,292,208)}else{let temp=document.createElement('canvas');temp.width=292;temp.height=208;let tc=temp.getContext('2d');tc.drawImage(imgs[0][f],0,0);let a=tc.getImageData(0,0,292,208);tc.clearRect(0,0,292,208);tc.drawImage(imgs[j][f],0,0);let b=tc.getImageData(0,0,292,208);let o=tc.createImageData(292,208);for(let k=0;k<a.data.length;k+=4){let s=a.data[k+3]>200,c=b.data[k+3]>200;if(s||c){o.data[k]=s&&c?242:c?240:0;o.data[k+1]=s&&c?242:s?210:0;o.data[k+2]=s&&c?242:s?230:190;o.data[k+3]=255}}tc.clearRect(0,0,292,208);tc.putImageData(o,0,0);ctx.drawImage(temp,x,y)}}
document.getElementById('framevalue').textContent=String(f).padStart(2,'0')+' · '+f*100+'–'+(f+1)*100+' ms';}
slider.addEventListener('input',draw);for(const id of ['overlay','bg','zoom'])document.getElementById(id).addEventListener('change',draw);
play.addEventListener('click',()=>{running=!running;play.textContent=running?'Pause':'Play';if(running)timer=setInterval(()=>{slider.value=(Number(slider.value)+1)%10;draw()},100);else clearInterval(timer)});
'''.replace('__FRAMES__',json.dumps(frames))
doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HoMM3 AI art and animation pipeline research</title><style>{css}</style></head><body><header><div class="eyebrow">Research + controlled asset experiment · 23 October 2026</div><h1>Production-quality AI art and animation for a faithful HoMM3 remaster</h1><p>Evidence, diagnosed failure modes, three executed Pikeman approaches, reproducible workflows and a recommended production process. Research candidates remain separate from production assets.</p></header><nav>{nav}</nav><main>{body}<footer>Prepared from the local project and cited primary sources. Tested outputs and researched-only techniques are labeled separately. No production roster changes.</footer></main><script>{js}</script></body></html>'''
(R/'report.html').write_text(doc)
print(json.dumps({'report':str(R/'report.html'),'bytes':len(doc.encode()),'sections':len(sections)}))
